// JSON/chunk-backed vocab access. This is the current production data source.
//
// The corpus is stored as 250-entry chunk files under public/data/chunks/
// (generated by scripts/split_vocab_chunks.ts). Chunks are lazy-loaded via
// fs.readFileSync and cached in module memory, so only requested chunks are
// read from disk.

import fs from "fs";
import path from "path";
import rawPopular from "@/public/data/popular_verbs_300.json";
import type { PopularVerb, VocabEntry } from "@/lib/types";
import {
  clampSearchLimit,
  matchesVocabSearch,
  normalizeSearchQuery,
  sortVocabEntries,
} from "@/lib/vocab-search";

const CHUNK_SIZE = 250;
const ENTRIES_PER_TRANCHE = 1000;
const NUM_TRANCHES = 13;
const CHUNKS_PER_TRANCHE = ENTRIES_PER_TRANCHE / CHUNK_SIZE;
const NUM_CHUNKS = (NUM_TRANCHES * ENTRIES_PER_TRANCHE) / CHUNK_SIZE;

const CHUNKS_DIR = path.join(process.cwd(), "public", "data", "chunks");
const POPULAR = rawPopular as PopularVerb[];
const POPULAR_IDS = new Set(POPULAR.map((v) => v.id));
const chunkCache = new Map<number, VocabEntry[]>();

function slim(entry: VocabEntry & { _quality?: unknown }): VocabEntry {
  const { _quality, ...rest } = entry;
  void _quality;
  return rest;
}

function loadChunk(index: number): VocabEntry[] {
  const cached = chunkCache.get(index);
  if (cached) return cached;

  const filePath = path.join(CHUNKS_DIR, `vocab_chunk_${index}.json`);
  const raw = JSON.parse(
    fs.readFileSync(filePath, "utf-8")
  ) as (VocabEntry & { _quality?: unknown })[];

  const entries = raw.map(slim);
  chunkCache.set(index, entries);
  return entries;
}

function chunksForTranche(trancheId: number): number[] {
  const start = (trancheId - 1) * CHUNKS_PER_TRANCHE;
  return Array.from({ length: CHUNKS_PER_TRANCHE }, (_, i) => start + i);
}

function chunkForId(id: number): number {
  return Math.floor((id - 1) / CHUNK_SIZE);
}

export const TRANCHE_IDS: number[] = Array.from(
  { length: NUM_TRANCHES },
  (_, i) => i + 1
);

export function getTrancheIds(): number[] {
  return TRANCHE_IDS;
}

export function getTrancheEntries(trancheId: number): VocabEntry[] {
  return chunksForTranche(trancheId).flatMap(loadChunk);
}

export function searchEntries(query: string, limit: number): VocabEntry[] {
  if (!normalizeSearchQuery(query)) return [];

  const matches: VocabEntry[] = [];
  for (let i = 0; i < NUM_CHUNKS; i++) {
    for (const entry of loadChunk(i)) {
      if (matchesVocabSearch(entry, query)) matches.push(entry);
    }
  }

  return sortVocabEntries(matches).slice(0, clampSearchLimit(limit));
}

export function getEntryById(id: number): VocabEntry | null {
  if (!Number.isSafeInteger(id) || id < 1 || id > NUM_CHUNKS * CHUNK_SIZE) {
    return null;
  }

  return loadChunk(chunkForId(id)).find((entry) => entry.id === id) ?? null;
}

export function getVocabIndex(): Record<number, number> {
  const index: Record<number, number> = {};
  for (let i = 0; i < NUM_CHUNKS; i++) {
    for (const entry of loadChunk(i)) {
      index[entry.id] = entry.tranche_id;
    }
  }
  return index;
}

export function getPopularEntries(): VocabEntry[] {
  const neededChunks = new Set<number>();
  for (const id of POPULAR_IDS) neededChunks.add(chunkForId(id));

  return [...neededChunks]
    .flatMap(loadChunk)
    .filter((entry) => POPULAR_IDS.has(entry.id))
    .sort((a, b) => a.frequency_rank - b.frequency_rank);
}

export function getEntriesByPos(pos: string, limit: number): VocabEntry[] {
  const results: VocabEntry[] = [];
  for (let i = 0; i < NUM_CHUNKS; i++) {
    for (const entry of loadChunk(i)) {
      if (entry.part_of_speech.includes(pos)) results.push(entry);
    }
  }
  results.sort((a, b) => a.frequency_rank - b.frequency_rank);
  return results.slice(0, limit);
}
